def comps(g,val):
    n,m=len(g),len(g[0]); seen=[[False]*m for _ in range(n)]; out=[]
    for r in range(n):
        for c in range(m):
            if g[r][c]==val and not seen[r][c]:
                q=deque([(r,c)]); seen[r][c]=True; cells=[]
                while q:
                    a,b=q.popleft(); cells.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        na,nb=a+da,b+db
                        if 0<=na<n and 0<=nb<m and g[na][nb]==val and not seen[na][nb]:
                            seen[na][nb]=True; q.append((na,nb))
                out.append(cells)
    return out
