def solve(g,keep_col_max):
    H,W=len(g),len(g[0])
    o=[list(row) for row in g]
    # lattice recolor everywhere
    for r in range(H):
        for c in range(W):
            if g[r][c]==2 and r%6==0 and c%6==0: o[r][c]=8
    # copy topmost shape into band (overwriting 3s)
    bs=comps(g)
    top=min(bs,key=lambda s:min(r for r,c in s))
    band=[r for r in range(H) if all(x==3 for x in g[r])]
    if not band: return o
    br=band[0]; btr=max(band)
    d=br-min(r for r,c in top)
    for r,c in top:
        nr=r+d
        if nr>btr: break
        if c<=keep_col_max: o[nr][c]=2
    return o
