import numpy as np
from collections import defaultdict

def comps_of(I,val):
    H,W=I.shape;seen=set();out=[]
    for r in range(H):
        for c in range(W):
            if I[r][c]==val and (r,c) not in seen:
                stack=[(r,c)];comp=set()
                while stack:
                    y,x=stack.pop()
                    if(y,x) in seen:continue
                    seen.add((y,x));comp.add((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        q=(y+dy,x+dx)
                        if 0<=q[0]<H and 0<=q[1]<W and I[q[0]][q[1]]==val and q not in seen: stack.append(q)
                out.append(comp)
    return out

