                    if 0<=rr<H and 0<=cc<W and I[rr][cc]==3: return None
            if I[r][c] in (0,2) or (r%5==0 and c%5==0): out[r][c]=I[r][c]
    Cs=[x for x in comps_of(I,2)]; Es=[(r,c) for r in range(H) for c in range(W) if r%5==0 and c%5==0]
    for cells in sorted(Cs,key=min):
        top=min(cells)
        near=[]
        for e in Es:
            d=(e[0]-top[0])**2+(e[1]-top[1])**2
            if d<9: near.append((d,e))
        if not near: continue
        d,e=min(near)
        out[e]=8; out[top[:1]]= [out[top[0]][t] for t in [top[1]] ] 
    # fill 3-region as pattern from demo: copy component shapes into 3-block at top-right-ish; erase rest of 3s... skip details here
    return out
